module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    input  e,
    output [24:0] out
);
  logic [4:0] ins;
  assign ins = {a, b, c, d, e};

  genvar i, j;
  generate
    for (i = 0; i < 5; i = i + 1) begin : gen_i
      for (j = 0; j < 5; j = j + 1) begin : gen_j
        assign out[24 - (i * 5 + j)] = ~ins[4-i] ^ ins[4-j];
      end
    end
  endgenerate

endmodule

