module tb_TopModule;
  reg a, b, c, d, e;
  wire [24:0] out;

  TopModule uut (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .e(e),
    .out(out)
  );

  initial begin
    integer i, j, k;
    reg [4:0] in_vals;
    reg [24:0] expected;
    reg [4:0] arr [0:4];
    int idx;

    for (i = 0; i < 32; i = i + 1) begin
      in_vals = i[4:0];
      a = in_vals[4];
      b = in_vals[3];
      c = in_vals[2];
      d = in_vals[1];
      e = in_vals[0];

      arr[0] = a;
      arr[1] = b;
      arr[2] = c;
      arr[3] = d;
      arr[4] = e;

      #1;

      idx = 24;
      for (int r = 0; r < 5; r = r + 1) begin
        for (int c_col = 0; c_col < 5; c_col = c_col + 1) begin
          // expected: ~(arr[r] ^ arr[c_col])? Wait, the prompt says ~a ^ a.
          // In Verilog, ~a ^ a is (~a) ^ a.
          reg bit_cmp;
          bit_cmp = (~arr[r]) ^ arr[c_col];
          if (out[idx] !== bit_cmp) begin
            $display("SELFFAIL: mismatch at inputs %b, r=%0d, c=%0d, idx=%0d: got %b, expected %b", 
                     in_vals, r, c_col, idx, out[idx], bit_cmp);
            $display("SELFTEST FAIL: mismatch");
            $finish;
          end
          idx = idx - 1;
        end
      end
    end

    $display("SELFTEST PASS");
    $finish;
  end
endmodule
